import {z} from 'zod';
import {GenderTarget, ProductStatus} from '@prisma/client';
import {field} from './custom.validation';
import {listQuerySchema} from '../utils/list';

// Categories, brands and products. Codes and SKUs are generated by the
// backend, so they are never part of these schemas.

const emptyToUndefined = (v: unknown) => (typeof v === 'string' && v.trim() === '' ? undefined : v);
const optionalId = (label: string) =>
    z.preprocess(emptyToUndefined, z.string().uuid(`Select a valid ${label}`).optional());
const text = (label: string, max: number) => field({label, kind: 'text', max, required: false});

// ---- Categories and brands -----------------------------------------------

const categoryBody = z.object({
    name: field({label: 'Category Name', kind: 'text', max: 60}),
    parentId: optionalId('Parent Category'),
    description: text('Description', 500),
    displayOrder: field({label: 'Display Order', kind: 'displayOrder', required: false}),
    seoTitle: text('SEO Title', 70),
    seoDesc: text('SEO Description', 160),
    isActive: z.boolean().default(true),
});

const brandBody = z.object({
    name: field({label: 'Brand Name', kind: 'text', max: 60}),
    description: text('Description', 500),
    website: field({label: 'Website', kind: 'url', required: false}),
    isActive: z.boolean().default(true),
});

const catalogListSchema = listQuerySchema(
    ['name', 'createdAt', 'displayOrder'] as const,
    'name',
).extend({
    sortDir: z.enum(['asc', 'desc']).default('asc'),
    active: z.enum(['true', 'false']).optional(),
});

// ---- Products ---------------------------------------------------------------

const price = (label: string) => field({label, kind: 'price'});

const variantBody = z.object({
    // Present when editing an existing variant
    id: z.string().uuid().optional(),
    size: field({label: 'Size', kind: 'text', max: 20}),
    color: field({label: 'Color', kind: 'text', max: 30}),
    colorHex: z.preprocess(
        emptyToUndefined,
        z
            .string()
            .regex(/^#[0-9a-fA-F]{6}$/, 'Enter a valid Color Code')
            .optional(),
    ),
    mrp: field({label: 'Variant MRP', kind: 'price', required: false}),
    sellingPrice: field({label: 'Variant Price', kind: 'price', required: false}),
    isActive: z.boolean().default(true),
});

const productFields = {
    name: field({label: 'Product Name', kind: 'text', max: 120}),
    categoryId: z.string({required_error: 'Category is required'}).uuid('Category is required'),
    brandId: optionalId('Brand'),
    shortDesc: text('Short Description', 300),
    detailedDesc: text('Detailed Description', 4000),
    tags: z.array(z.string().trim().min(1).max(30)).max(15, 'At most 15 tags').default([]),
    gender: z.nativeEnum(GenderTarget).default(GenderTarget.UNISEX),
    productType: text('Product Type', 60),
    fabric: text('Fabric', 60),
    pattern: text('Pattern', 60),
    fit: text('Fit', 60),
    sleeveType: text('Sleeve Type', 60),
    neckType: text('Neck Type', 60),
    occasion: text('Occasion', 60),
    season: text('Season', 60),
    careInstructions: text('Care Instructions', 300),
    countryOfOrigin: text('Country of Origin', 60),
    mrp: price('MRP'),
    sellingPrice: price('Selling Price'),
    taxRate: z.coerce
        .number()
        .refine((v) => [0, 5, 12, 18].includes(v), 'Tax Rate must be 0, 5, 12 or 18%')
        .default(5),
    weightKg: z.preprocess(
        emptyToUndefined,
        z.coerce.number().positive('Weight must be more than 0').max(100).optional(),
    ),
    dimensions: text('Dimensions', 40),
    returnEligible: z.boolean().default(true),
    returnPeriodDays: z.coerce
        .number()
        .int()
        .min(0)
        .max(30, 'Return Period can be at most 30 days')
        .default(7),
    seoTitle: text('SEO Title', 70),
    seoDesc: text('SEO Description', 160),
    variants: z.array(variantBody).min(1, 'Add at least one variant (size / color)').max(60),
};

type ProductShape = Partial<{
    mrp: number;
    sellingPrice: number;
    variants: z.infer<typeof variantBody>[];
}>;

const productRules = (v: ProductShape, ctx: z.RefinementCtx) => {
    if (v.mrp !== undefined && v.sellingPrice !== undefined && v.sellingPrice > v.mrp) {
        ctx.addIssue({
            code: 'custom',
            path: ['sellingPrice'],
            message: 'Selling Price cannot be more than MRP',
        });
    }
    // One row per size + color
    const seen = new Set<string>();
    v.variants?.forEach((variant, i) => {
        const key = `${variant.size.toLowerCase()}|${variant.color.toLowerCase()}`;
        if (seen.has(key)) {
            ctx.addIssue({
                code: 'custom',
                path: ['variants', i, 'size'],
                message: 'This size and color is already listed',
            });
        }
        seen.add(key);
        if (
            variant.mrp !== undefined &&
            variant.sellingPrice !== undefined &&
            variant.sellingPrice > variant.mrp
        ) {
            ctx.addIssue({
                code: 'custom',
                path: ['variants', i, 'sellingPrice'],
                message: 'Variant Price cannot be more than Variant MRP',
            });
        }
    });
};

const createProductSchema = z.object(productFields).superRefine(productRules);
const updateProductSchema = z.object(productFields).partial().superRefine(productRules);

const productListSchema = listQuerySchema(
    ['createdAt', 'name', 'sku', 'sellingPrice', 'status'] as const,
    'createdAt',
).extend({
    status: z.nativeEnum(ProductStatus).optional(),
    categoryId: z.string().uuid().optional(),
    brandId: z.string().uuid().optional(),
    companyId: z.string().uuid().optional(),
    gender: z.nativeEnum(GenderTarget).optional(),
});

const productStatusSchema = z.object({
    status: z.enum([
        ProductStatus.DRAFT,
        ProductStatus.PUBLISHED,
        ProductStatus.UNPUBLISHED,
        ProductStatus.ARCHIVED,
    ]),
    reason: z.string().trim().max(500).optional(),
});

const imageUpdateSchema = z.object({
    altText: text('Alt Text', 120),
    isMain: z.boolean().optional(),
    order: z.coerce.number().int().min(0).max(100).optional(),
});

const idSchema = z.object({id: z.string().uuid('Invalid id')});
const imageIdSchema = z.object({id: z.string().uuid(), imageId: z.string().uuid('Invalid image')});

export default {
    createCategorySchema: categoryBody,
    updateCategorySchema: categoryBody.partial(),
    createBrandSchema: brandBody,
    updateBrandSchema: brandBody.partial(),
    catalogListSchema,
    createProductSchema,
    updateProductSchema,
    productListSchema,
    productStatusSchema,
    imageUpdateSchema,
    idSchema,
    imageIdSchema,
};
